{
  "root": "main_stack",
  "state": {
    "itinerary_days": [
      {
        "dayTitle": "Day 1: The Heart of the Renaissance",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/Florence_Duomo_from_Michelangelo_Square.jpg/1200px-Florence_Duomo_from_Michelangelo_Square.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/building.svg",
        "morning": "Explore the Piazza del Duomo, including the interior of the Cathedral and the Baptistery's golden doors.",
        "afternoon": "Visit the San Lorenzo Leather Market for high-quality Italian craftsmanship and souvenirs.",
        "dinner": "Trattoria Mario — Famous for authentic Ribollita and a lively, traditional atmosphere.",
        "actionLabel": "View Market Map",
        "actionUrl": "https://www.mercatocentrale.com/florence/"
      },
      {
        "dayTitle": "Day 2: Michelangelo and Sacred Art",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/David_von_Michelangelo.jpg/1200px-David_von_Michelangelo.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/star.svg",
        "morning": "View Michelangelo’s David at the Accademia Gallery (advance booking essential).",
        "afternoon": "Tour the Basilica di Santa Croce, the burial place of Michelangelo, Galileo, and Machiavelli.",
        "dinner": "Regina Bistecca — Specializes in the iconic Bistecca alla Fiorentina, served by weight.",
        "actionLabel": "Accademia Tickets",
        "actionUrl": "https://www.galleriaaccademiafirenze.it/en/"
      },
      {
        "dayTitle": "Day 3: The Oltrarno Artisan District",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/16/Palazzo_pitti_08.jpg/1200px-Palazzo_pitti_08.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/house.svg",
        "morning": "Visit the Pitti Palace and its Palatine Gallery to see works by Raphael and Titian.",
        "afternoon": "Wander the Oltrarno neighborhood to visit active workshops of goldsmiths and bookbinders.",
        "dinner": "Osteria Santo Spirito — Known for truffle gnocchi and traditional Pappardelle sulla Lepre.",
        "actionLabel": "Explore Oltrarno",
        "actionUrl": "https://www.visitflorence.com/itineraries-in-florence/oltrarno-neighborhood.html"
      },
      {
        "dayTitle": "Day 4: Tuscan Hillside Excursion",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Fiesole_Teatro_Romano_2.jpg/1200px-Fiesole_Teatro_Romano_2.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/signpost-split.svg",
        "morning": "Take Bus #7 from Piazza San Marco to Fiesole (20 mins) to see the Roman Theater and Etruscan ruins.",
        "afternoon": "Return to Florence for the Mercato Nuovo and the \"Porcellino\" bronze boar for good luck.",
        "dinner": "Trattoria Da Rocco — Located in the Sant'Ambrogio Market, offering seasonal Pappa al Pomodoro.",
        "actionLabel": "Fiesole Bus Info",
        "actionUrl": "https://www.at-bus.it/en"
      },
      {
        "dayTitle": "Day 5: Masterpieces of the Uffizi",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Uffizi_Gallery_Florence_Italy.jpg/1200px-Uffizi_Gallery_Florence_Italy.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/map.svg",
        "morning": "Extensive tour of the Uffizi Gallery, home to Botticelli’s \"Birth of Venus\" and Da Vinci’s works.",
        "afternoon": "A final stroll across the Ponte Vecchio and a visit to the Ferragamo Shoe Museum for fashion history.",
        "dinner": "Buca Lapi — Set in a historic cellar, serving premium Tuscan steaks and local Chianti Classico.",
        "actionLabel": "Uffizi Gallery Info",
        "actionUrl": "https://www.uffizi.it/en/the-uffizi"
      }
    ],
    "museum_bookings": [
      {
        "Museum": "Uffizi Gallery",
        "Entry Fee": "€25.00",
        "Booking Required": "Yes (Strict)",
        "Primary Focus": "Botticelli & Da Vinci"
      },
      {
        "Museum": "Accademia Gallery",
        "Entry Fee": "€16.00",
        "Booking Required": "Yes (Strict)",
        "Primary Focus": "Michelangelo's David"
      },
      {
        "Museum": "Pitti Palace",
        "Entry Fee": "€16.00",
        "Booking Required": "Recommended",
        "Primary Focus": "Medici Private Collection"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "context_title",
        "context_text",
        "itinerary_title",
        "itinerary_table",
        "museum_booking_title",
        "museum_booking_table",
        "quick_actions_title",
        "quick_actions_stack",
        "sources_title",
        "sources_stack"
      ]
    },
    "context_title": {
      "type": "Text",
      "props": {
        "text": "Florence Renaissance and Culinary Context",
        "variant": "h3"
      },
      "children": []
    },
    "context_text": {
      "type": "Text",
      "props": {
        "text": "This itinerary is designed for three adults with a focus on accessible Renaissance masterpieces and traditional Tuscan dining. The daily budget of €200 per person comfortably covers high-end museum entries, taxi or bus transport, and premium dining experiences. All selected activities avoid steep climbs or strenuous hiking, utilizing elevators where available and focusing on ground-level exploration."
      },
      "children": []
    },
    "itinerary_title": {
      "type": "Text",
      "props": {
        "text": "5-Day Florence Cultural Schedule",
        "variant": "h3"
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "statePath": "/itinerary_days",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "dayTitle",
        "highlightColumns": [
          "morning",
          "dinner"
        ],
        "columns": [
          {
            "key": "dayTitle",
            "label": "Day"
          },
          {
            "key": "image",
            "label": "Image"
          },
          {
            "key": "icon",
            "label": "Icon"
          },
          {
            "key": "morning",
            "label": "Morning"
          },
          {
            "key": "afternoon",
            "label": "Afternoon"
          },
          {
            "key": "dinner",
            "label": "Dinner"
          },
          {
            "key": "actionLabel",
            "label": "Action"
          },
          {
            "key": "actionUrl",
            "label": "URL"
          }
        ]
      },
      "children": []
    },
    "museum_booking_title": {
      "type": "Text",
      "props": {
        "text": "Essential Museum Booking Details",
        "variant": "h3"
      },
      "children": []
    },
    "museum_booking_table": {
      "type": "Table",
      "props": {
        "statePath": "/museum_bookings",
        "domain": "generic",
        "preferredPresentation": "table",
        "columns": [
          {
            "key": "Museum",
            "label": "Museum"
          },
          {
            "key": "Entry Fee",
            "label": "Entry Fee"
          },
          {
            "key": "Booking Required",
            "label": "Booking Required"
          },
          {
            "key": "Primary Focus",
            "label": "Primary Focus"
          }
        ]
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "quick_action_book_museums",
        "quick_action_find_flights",
        "quick_action_florence_tourism"
      ]
    },
    "quick_action_book_museums": {
      "type": "Button",
      "props": {
        "label": "Book Museum Tickets"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.getyourguide.com/florence-l32/museums-tours-tc1/"
          }
        }
      },
      "children": []
    },
    "quick_action_find_flights": {
      "type": "Button",
      "props": {
        "label": "Find Flights to Florence"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.google.com/flights?q=flights+to+florence"
          }
        }
      },
      "children": []
    },
    "quick_action_florence_tourism": {
      "type": "Button",
      "props": {
        "label": "Florence Official Tourism Site"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.visitflorence.com/en/"
          }
        }
      },
      "children": []
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "source_visit_florence",
        "source_uffizi"
      ]
    },
    "source_visit_florence": {
      "type": "Button",
      "props": {
        "label": "Visit Florence (Official Tourism)"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.visitflorence.com/en/"
          }
        }
      },
      "children": []
    },
    "source_uffizi": {
      "type": "Button",
      "props": {
        "label": "Uffizi Gallery Official Site"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.uffizi.it/en/"
          }
        }
      },
      "children": []
    }
  }
}
